export function initGarageGame(){
  const section=document.createElement('section');section.className='section arcade';section.id='garage-run';
  section.innerHTML=`<div class="arcade-copy"><span class="eyebrow">HAZ UNA PARADA. CAMBIA DE RITMO.</span><h2>Tu próxima aventura<br><em>empieza jugando.</em></h2><p>Un auto, tres carriles y tus reflejos. Esquiva el tráfico, recoge las luces rojas y supera tu propio récord.</p><div class="arcade-tags"><span>Teclado y móvil</span><span>Partidas rápidas</span></div><button class="button" id="open-garage-game">Jugar a Garage Run</button><small>Un minijuego de Torres Garage · Récord guardado en este dispositivo</small></div><button class="arcade-preview" aria-label="Abrir el minijuego Garage Run"><span class="arcade-grid" aria-hidden="true"></span><span class="arcade-wordmark">GARAGE<span>RUN</span></span><span class="arcade-preview-car" aria-hidden="true"><i></i></span><span class="arcade-play">▷</span><span class="arcade-caption">ENCIENDE TU PRÓXIMA HISTORIA</span></button>`;
  document.querySelector('#nosotros').before(section);
  const progress=document.createElement('div');progress.className='page-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let progressFrame=null;function updateProgress(){progressFrame=null;const distance=document.documentElement.scrollHeight-innerHeight;progress.style.setProperty('--reading-progress',String(distance>0?scrollY/distance:0));}window.addEventListener('scroll',()=>{if(progressFrame===null)progressFrame=requestAnimationFrame(updateProgress);},{passive:true});window.addEventListener('resize',updateProgress);updateProgress();
  const dialog=document.createElement('dialog');dialog.className='game-dialog';dialog.setAttribute('aria-label','Garage Run, minijuego de conducción');
  dialog.innerHTML=`<div class="game-top"><span>GARAGE <b>RUN</b></span><div><button class="game-pause" aria-label="Pausar partida">Ⅱ</button><button class="game-exit" aria-label="Salir del minijuego">×</button></div></div><div class="game-hud"><div><small>PUNTOS</small><strong id="game-score">0</strong></div><div><small>RÉCORD</small><strong id="game-best">0</strong></div><div><small>RITMO</small><strong id="game-speed">1</strong></div></div><div class="game-stage"><canvas width="480" height="720" tabindex="0" aria-label="Pista de tres carriles. Usa las flechas izquierda y derecha o los botones para esquivar el tráfico."></canvas><div class="game-overlay"><span class="eyebrow">TORRES GARAGE ARCADE</span><h2 id="game-title">La pista es tuya.</h2><p id="game-description">Esquiva los autos y recoge luces rojas.<br>Usa ← → o A / D. En móvil, desliza o toca los controles.</p><button class="button" id="game-start">Empezar a conducir</button></div><div class="game-toast" aria-hidden="true">+50</div></div><div class="game-controls"><button id="game-left" aria-label="Cambiar al carril izquierdo"><svg viewBox="0 0 24 24"><path d="m14 5-7 7 7 7"/></svg></button><span>DESLIZA O CAMBIA DE CARRIL<small>Espacio para pausar</small></span><button id="game-right" aria-label="Cambiar al carril derecho"><svg viewBox="0 0 24 24"><path d="m10 5 7 7-7 7"/></svg></button></div><p class="game-status" role="status" aria-live="polite"></p>`;
  document.body.append(dialog);
  const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),overlay=dialog.querySelector('.game-overlay'),start=dialog.querySelector('#game-start'),pauseButton=dialog.querySelector('.game-pause');
  const lanes=[122,240,358];let state='ready',lane=1,playerX=240,elapsed=0,points=0,bonus=0,best=0,objects=[],spawn=0,frame=null,last=null,roadOffset=0,toast=0,accumulator=0;
  const scoreLabel=dialog.querySelector('#game-score'),bestLabel=dialog.querySelector('#game-best'),speedLabel=dialog.querySelector('#game-speed');
  try{const stored=Number(localStorage.getItem('torres-game-best'));best=Number.isFinite(stored)?Math.max(0,stored):0;}catch{}
  function resizeCanvas(){if(!dialog.open)return;const ratio=Math.max(.5,Math.min(2,canvas.getBoundingClientRect().width/480*(devicePixelRatio||1)));const width=Math.round(480*ratio),height=Math.round(720*ratio);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;ctx.setTransform(width/480,0,0,height/720,0,0);}paint();}
  new ResizeObserver(resizeCanvas).observe(dialog.querySelector('.game-stage'));
  function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
  function car(x,y,color,player=false){ctx.save();ctx.translate(x,y);ctx.shadowColor=player?'#ed174850':'#0008';ctx.shadowBlur=player?22:10;rounded(-25,-38,50,80,12,color);ctx.shadowBlur=0;rounded(-21,-21,42,20,5,'#142131');rounded(-20,19,40,13,4,'#172331');rounded(-18,1,36,15,3,player?'#c10830':'#536271');rounded(-29,-25,5,17,2,'#070b10');rounded(24,-25,5,17,2,'#070b10');rounded(-29,20,5,17,2,'#070b10');rounded(24,20,5,17,2,'#070b10');rounded(-20,-36,11,4,2,'#ecf6ff');rounded(9,-36,11,4,2,'#ecf6ff');rounded(-20,36,9,4,2,'#fa2049');rounded(11,36,9,4,2,'#fa2049');if(player){const beam=ctx.createLinearGradient(0,-110,0,-35);beam.addColorStop(0,'#c7eaff00');beam.addColorStop(1,'#c7eaff20');ctx.fillStyle=beam;ctx.beginPath();ctx.moveTo(-18,-36);ctx.lineTo(-42,-120);ctx.lineTo(42,-120);ctx.lineTo(18,-36);ctx.fill();}ctx.restore();}
  function paint(){ctx.clearRect(0,0,480,720);ctx.fillStyle='#080e17';ctx.fillRect(0,0,480,720);const glow=ctx.createLinearGradient(0,0,480,0);glow.addColorStop(0,'#1c101e');glow.addColorStop(.5,'#172330');glow.addColorStop(1,'#1c101e');ctx.fillStyle=glow;ctx.fillRect(64,0,352,720);ctx.strokeStyle='#f5295270';ctx.lineWidth=2;for(const x of [66,414]){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,720);ctx.stroke();}ctx.strokeStyle='#dce8ff28';ctx.lineWidth=3;ctx.setLineDash([30,36]);ctx.lineDashOffset=-roadOffset;for(const x of [181,299]){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,720);ctx.stroke();}ctx.setLineDash([]);for(let y=-80;y<800;y+=105){const yy=(y+roadOffset*1.4)%840;rounded(29,yy,5,22,2,'#f5224955');rounded(446,yy,5,22,2,'#f5224955');}for(const obj of objects){if(obj.kind==='car')car(lanes[obj.lane],obj.y,obj.color);else{ctx.save();ctx.shadowColor='#f52750';ctx.shadowBlur=16;ctx.strokeStyle='#ff4c72';ctx.lineWidth=4;ctx.beginPath();ctx.arc(lanes[obj.lane],obj.y,13,0,Math.PI*2);ctx.stroke();ctx.restore();}}car(playerX,592,'#f0254e',true);if(toast>0){ctx.fillStyle=`rgba(255,105,137,${Math.min(1,toast*2)})`;ctx.font='bold 23px Inter, Arial';ctx.textAlign='center';ctx.fillText('+50',playerX,520-(1-toast)*30);}}
  function hud(){const rhythm=String(1+Math.floor(elapsed/15));if(scoreLabel.textContent!==String(points))scoreLabel.textContent=points;if(bestLabel.textContent!==String(best))bestLabel.textContent=best;if(speedLabel.textContent!==rhythm)speedLabel.textContent=rhythm;}
  function halt(){if(frame!==null)cancelAnimationFrame(frame);frame=null;last=null;accumulator=0;}
  function finish(){state='over';halt();if(points>best){best=points;try{localStorage.setItem('torres-game-best',String(best));}catch{}}hud();overlay.hidden=false;dialog.querySelector('#game-title').textContent='Una curva más.';dialog.querySelector('#game-description').textContent=`Conseguiste ${points} puntos. Tu récord: ${best}. ¿Listo para otra vuelta?`;start.textContent='Volver a intentarlo';pauseButton.disabled=true;dialog.querySelector('.game-status').textContent=`Partida terminada. ${points} puntos.`;start.focus({preventScroll:true});}
  function advance(dt){elapsed+=dt;const speed=Math.min(430,210+elapsed*2.4);roadOffset=(roadOffset+speed*dt)%660;playerX+=(lanes[lane]-playerX)*(1-Math.exp(-dt*16));spawn-=dt;toast=Math.max(0,toast-dt);if(spawn<=0){const nextLane=Math.floor(Math.random()*3);objects.push({kind:'car',lane:nextLane,y:-90,color:['#c4d0db','#64798f','#d4b37e'][Math.floor(Math.random()*3)]});if(Math.random()<.7)objects.push({kind:'light',lane:(nextLane+1+Math.floor(Math.random()*2))%3,y:-160});spawn=Math.max(.7,1.35-elapsed*.004);}for(const obj of objects){obj.y+=speed*dt;if(obj.kind==='car'&&Math.abs(obj.y-592)<65&&Math.abs(lanes[obj.lane]-playerX)<44){paint();finish();return;}if(obj.kind==='light'&&Math.abs(obj.y-592)<42&&Math.abs(lanes[obj.lane]-playerX)<35){obj.y=1000;bonus+=50;toast=1;}}objects=objects.filter(o=>o.y<810);points=Math.floor(elapsed*12)+bonus;}
  function tick(now){frame=null;if(state!=='playing')return;accumulator+=last===null?0:Math.min((now-last)/1000,.12);last=now;const step=1/120;while(accumulator>=step&&state==='playing'){accumulator-=step;advance(step);}if(state!=='playing')return;hud();paint();frame=requestAnimationFrame(tick);}
  function play(){if(state!=='paused'){lane=1;playerX=240;elapsed=0;bonus=0;points=0;spawn=1.2;roadOffset=0;objects=[];toast=0;}halt();state='playing';overlay.hidden=true;pauseButton.disabled=false;pauseButton.setAttribute('aria-label','Pausar partida');pauseButton.textContent='Ⅱ';dialog.querySelector('.game-status').textContent='Partida iniciada.';canvas.focus({preventScroll:true});hud();frame=requestAnimationFrame(tick);}
  function pause(){if(state!=='playing')return;state='paused';halt();overlay.hidden=false;dialog.querySelector('#game-title').textContent='Una breve parada.';dialog.querySelector('#game-description').textContent='Tu partida te espera. Vuelve a la pista cuando quieras.';start.textContent='Continuar partida';pauseButton.setAttribute('aria-label','Reanudar partida');pauseButton.textContent='▷';dialog.querySelector('.game-status').textContent='Partida en pausa.';}
  function move(direction){if(state==='playing')lane=Math.max(0,Math.min(2,lane+direction));}
  function open(){halt();dialog.showModal();document.body.style.overflow='hidden';state='ready';overlay.hidden=false;dialog.querySelector('#game-title').textContent='La pista es tuya.';dialog.querySelector('#game-description').textContent='Esquiva los autos y recoge luces rojas. Usa ← → o A / D. En móvil, desliza o toca los controles.';start.textContent='Empezar a conducir';pauseButton.disabled=true;objects=[];playerX=240;points=0;roadOffset=0;hud();resizeCanvas();start.focus({preventScroll:true});}
  section.querySelector('#open-garage-game').onclick=open;section.querySelector('.arcade-preview').onclick=open;start.onclick=play;pauseButton.onclick=()=>state==='playing'?pause():state==='paused'?play():null;dialog.querySelector('.game-exit').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{halt();state='ready';document.body.style.overflow='';});dialog.querySelector('#game-left').onclick=()=>move(-1);dialog.querySelector('#game-right').onclick=()=>move(1);
  dialog.addEventListener('keydown',event=>{if(event.target.closest('button')&&(event.key===' '||event.key==='Enter'))return;if(['ArrowLeft','ArrowRight','a','A','d','D',' '].includes(event.key)){event.preventDefault();if(event.key===' ')state==='playing'?pause():state==='paused'?play():null;else move(['ArrowLeft','a','A'].includes(event.key)?-1:1);}});
  let swipe=null;canvas.addEventListener('pointerdown',event=>{if(event.button!==0||state!=='playing')return;swipe={id:event.pointerId,x:event.clientX,y:event.clientY};canvas.setPointerCapture(event.pointerId);});canvas.addEventListener('pointermove',event=>{if(!swipe||event.pointerId!==swipe.id)return;const dx=event.clientX-swipe.x,dy=event.clientY-swipe.y;if(Math.abs(dx)>=Math.max(24,canvas.clientWidth*.12)&&Math.abs(dx)>Math.abs(dy)){move(dx<0?-1:1);swipe.x=event.clientX;swipe.y=event.clientY;}});function endSwipe(event){if(swipe?.id===event.pointerId)swipe=null;}canvas.addEventListener('pointerup',endSwipe);canvas.addEventListener('pointercancel',endSwipe);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('blur',pause);window.addEventListener('resize',()=>{if(dialog.open){pause();resizeCanvas();}});
  if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){section.classList.add('arcade-visible');observer.disconnect();}},{threshold:.1});observer.observe(section);}else section.classList.add('arcade-visible');
}
